"""Summarize node sequence gaps without changing the node."""
import json
from collections import Counter
from pathlib import Path
import re
import stat
import sys

SEGMENT = re.compile(r"(obs|must)\.([0-9]{12})\.jsonl\Z")
CHANNELS = ("obs", "must")


def reject_constant(value):
    raise ValueError("non-finite JSON constant: " + value)


def regular(path):
    try:
        return stat.S_ISREG(path.lstat().st_mode)
    except FileNotFoundError:
        return False


def read_record(line):
    try:
        value = json.loads(line.decode("utf-8"), parse_constant=reject_constant)
    except (UnicodeError, ValueError):
        return None, "bad_json"
    if not isinstance(value, dict) or type(value.get("seq")) is not int or value["seq"] < 1:
        return None, "no_seq"
    return value["seq"], None


def channel_files(folder, channel, segments):
    paths = sorted(segments[channel], key=lambda item: (item[0], item[1].name))
    active = folder / (channel + ".active.jsonl")
    if regular(active):
        paths.append((None, active))
    return [path for _, path in paths]


def summarize(folder):
    segments = {channel: [] for channel in CHANNELS}
    for path in folder.iterdir():
        match = SEGMENT.fullmatch(path.name)
        if match and regular(path):
            segments[match.group(1)].append((int(match.group(2)), path))

    bad = []
    channels = {}
    seen = {}
    for channel in CHANNELS:
        seqs = []
        for path in channel_files(folder, channel, segments):
            parts = path.read_bytes().split(b"\n")
            for number, line in enumerate(parts[:-1], 1):
                seq, why = read_record(line)
                if why:
                    bad.append({"file": path.name, "line": number, "why": why})
                else:
                    seqs.append(seq)
            if parts[-1]:
                bad.append({"file": path.name, "line": len(parts), "why": "torn"})
        counts = Counter(seqs)
        unique = sorted(counts)
        seen[channel] = unique
        channels[channel] = {
            "count": len(seqs),
            "first": unique[0] if unique else None,
            "last": unique[-1] if unique else None,
            "missing": [[a + 1, b - 1] for a, b in zip(unique, unique[1:]) if b > a + 1],
            "dup": [seq for seq in unique if counts[seq] >= 2],
            "next_seq": None,
            "unacked": None,
            "stale_next": None,
        }

    state_path = folder / "state.json"
    try:
        present = state_path.lstat()
    except FileNotFoundError:
        present = None
    if present is not None:
        state = None
        if stat.S_ISREG(present.st_mode):
            try:
                state = json.loads(state_path.read_text(encoding="utf-8"),
                                   parse_constant=reject_constant)
            except (OSError, UnicodeError, ValueError):
                pass
        entries = state.get("channels") if isinstance(state, dict) else None
        invalid = not isinstance(entries, dict)
        if not invalid:
            for channel in CHANNELS:
                entry = entries.get(channel)
                valid = isinstance(entry, dict) and type(entry.get("next_seq")) is int
                if channel == "must":
                    valid = valid and type(entry.get("acked_upto")) is int
                if not valid:
                    invalid = True
                    continue
                result = channels[channel]
                result["next_seq"] = entry["next_seq"]
                if channel == "must":
                    result["unacked"] = sum(seq > entry["acked_upto"] for seq in seen[channel])
                if result["last"] is not None:
                    result["stale_next"] = entry["next_seq"] != result["last"] + 1
        if invalid:
            bad.append({"file": "state.json", "line": None, "why": "bad_state"})
    bad.sort(key=lambda item: (item["file"], 0 if item["line"] is None else item["line"], item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 1 or not Path(args[0]).is_dir():
        return 2
    print(json.dumps(summarize(Path(args[0])), separators=(",", ":"), allow_nan=False))
    return 0


if __name__ == "__main__":
    sys.exit(main())
